// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT, LogFile} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 100 ether);
        vm.deal(address(c), amount);

        Reverter r = new Reverter();
        c.SetLogFile(address(new LogFile()));

        uint256 startBal = c.balances(address(r));
        vm.prank(address(r));
        vm.deal(address(r), amount);
        r.depositC(address(c), amount);

        uint256 preBal = c.balances(address(r));
        vm.prank(address(r));
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));

        uint256 postBal = c.balances(address(r));

        assertTrue(!ok && postBal == preBal);
    }
}

contract Reverter {
    receive() external payable {
        revert();
    }

    function depositC(address c, uint256 amount) external {
        (bool s, ) = c.call{value: amount}(abi.encodeWithSignature("Deposit()"));
        require(s, "deposit failed");
    }
}
